justifyContent: 'center',
// The non-interactive single-label footprint from the size-chip Figma component set's
// other Type — no matching width-scale token for 65px; height reuses the same
// --zimm-scale-700 (28px) the ZimmSizeChip atom's own `chip` part uses, since it is the
// same row height as the interactive variant.
// audit-allow: 65px — no foundation width token exists for this exact non-interactive
// label size
width: '65px',
height: 'var(--zimm-scale-700)',
// No token named for this specific "primary/dark border" purpose exists in the
// `border` alias tier (see foundation/colour.ts) — only default/secondary/focus/
// forms/error. The value here is confirmed directly against Figma node

 * padding" and "Header horizontal insets" sections entirely.
 */

// Horizontal card-to-card gap, Desktop only now — see this file's own "HORIZONTAL GAP" docblock
// section above for the full per-breakpoint correction. rem, not px, matching
// zimmRecentlyViewedRail.css.ts's CARD_WIDTH_MOBILE/TABLET/DESKTOP precedent for a sizing
// (non-hairline) dimension with no foundation token yet.
const GRID_CARD_GAP_DESKTOP = '6rem'; // 96px — confirmed Figma value, checked at two independent sources (40000301:11694 "Product Card Group" master, Size=Desktop/Display=4, node 40000307:12446; and the page-level instance 3332:35655). No --zimm-scale-* equivalent (nearest neighbours: named scale 5xl=80px / 6xl=128px; numeric alias 1600=64px jumps straight to 3500=140px) — pending promotion to foundation/spacing.ts or sizes.ts by the UI designer.

// Column counts per breakpoint — see this file's own "COLUMN COUNT PER BREAKPOINT" docblock
// section above for the full reasoning and sourcing (Desktop is a confirmed Figma reading; Mobile
// and Tablet are Marcel's own direct figures, 2026-09-08, not re-derived design-asset readings).
const GRID_COLUMNS_BASE = 2; // Mobile only (below breakpoints.md) — Marcel, 2026-09-08.
const GRID_COLUMNS_TABLET = 3; // breakpoints.md up, below breakpoints.xl — Marcel, 2026-09-08.
const GRID_COLUMNS_DESKTOP = 4; // breakpoints.xl and up — confirmed (Figma nodes cited in the docblock above).

// Same Tablet/Desktop query convention (name and breakpoint) as zimmRecentlyViewedRail.css.ts's
// own identically-named constants.
const TABLET_UP_QUERY = `@media (min-width: ${breakpoints.md})`; // 768px
const DESKTOP_UP_QUERY = `@media (min-width: ${breakpoints.xl})`; // 1280px — the confirmed 4-up/288px reading itself comes from a 1440px Figma frame, inside this tier.

// Content max-width — fixed 2026-09-08, same root cause and same fix shape as
// zimmRecentlyViewedRail.css.ts's own identical bug found via live testing the same day: with no
// cap, `container`'s `width: '100%'` (and `grid`'s own, below) stretch to whatever width the page
// actually provides — confirmed via Storybook screenshot that this genuinely oversizes every card
// beyond the confirmed 288px reading, not just a cosmetic nit. 1440px is the same confirmed value
// `GRID_CARD_GAP_DESKTOP`'s own docblock derives from (4 x 288px cards + 3 x 96px gaps) — restated here as
// a width cap rather than a per-card value. Desktop-only, matching the fact that the 4-column
// layout itself only applies from this breakpoint up; neither the Mobile (2-column) nor Tablet
// (3-column) tier has a confirmed reference *width* to cap against — Marcel's own figures above
// are column counts, not card widths or a max-width reading — so both stay fluid, same "don't
// guess" reasoning as the column counts' own docblock section.
// audit-allow: derived composite (already-pending card width x confirmed column/gap counts),
// not itself a value with any promotable foundation-token equivalent.
const GRID_CONTENT_MAX_WIDTH_DESKTOP = '90rem'; // 1440px = (288px x 4 cards) + (96px x 3 gaps)

// Header padding — corrected 2026-09-10, replacing both the old "Header vertical padding" and
// "Header horizontal insets" sections (see the module docblock's own "TITLE ROW PADDING" note for
// the full correction narrative). Checked directly against the three real page-composition frames
// rather than the single provisional bar node the previous revision relied on:

// Card min-width floor, Mobile/Tablet (also applied at Desktop — see docblock for why one
// uniform floor is correct there too) — see docblock's "CARD SIZING" section. rem, not px,
// matching footer.css.ts's SIZE_COL_SUB/SIZE_COL_MAP precedent for a sizing (non-hairline)
// dimension with no foundation token yet.
const CARD_MIN_WIDTH_MOBILE_TABLET = '12.5rem'; // 200px — confirmed Figma value (flex: 1 0 0, min-width: 200px on the real Mobile 40000538:25030 and Tablet 40000730:13363 Product-card instances, via get_design_context). No --zimm-scale-* equivalent (nearest neighbours: 1600=64px, 3500=140px) — pending promotion to foundation/spacing.ts or sizes.ts by the UI designer.

// Each card's share of the row, sized against the per-breakpoint *cap* (RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS)
// rather than however many cards actually render — see docblock's "Under-populated rows" section.
// Derived, not hand-typed, so this can never silently drift from the cap it depends on.
const CARD_ROW_SHARE_MOBILE = `${(100 / RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.base).toFixed(4)}%`; // 2 cards -> 50%
const CARD_ROW_SHARE_TABLET = `${(100 / RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.md).toFixed(4)}%`; // 3 cards -> 33.3333%
const CARD_ROW_SHARE_DESKTOP = `${(100 / RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.xl).toFixed(4)}%`; // 5 cards -> 20%

// Header (title-and-link row) height — see docblock. Same pending-token treatment as the card
// widths above; neither value exists anywhere in zimmTokens.ts's numeric scale.
const HEADER_HEIGHT_MOBILE = '3.5rem'; // 56px — confirmed Figma value (node 40000538:25031, Mobile — also covers Tablet, see docblock). Pending promotion.
const HEADER_HEIGHT_DESKTOP = '6rem'; // 96px — confirmed Figma value (node 40000538:20306, Desktop). Pending promotion.

// Rail content max-width, per breakpoint — corrected 2026-09-10 (was fixed 2026-09-08, then found
// wrong by the same Figma-vs-code audit that fixed CARD_MIN_WIDTH_MOBILE_TABLET above). Without a
// cap, `container`'s bare `width: '100%'` stretches to whatever width the page actually provides —
// this site's own grid foundation is deliberately uncapped (gridSystem.ts's `grid.maxWidth:
// 'none'`), so nothing above this component was ever going to constrain it on its own.
//
// The 2026-09-08 values (402px/768px/1440px) were derived from the same now-corrected card-width x
// visible-count arithmetic the card fix above closes (201x2=402, 256x3=768, 288x5=1440) — a real
// bug in its own right, now fixed here too: checked directly against each breakpoint's own master
// component (`get_design_context`, not just a page instance, which can be resized/overridden by
// its own parent frame and so doesn't reveal the component's real intrinsic rule):
//   - Mobile (`40000538:25030`): fluid, capped at 767px (not hard-set to 402px).
//   - Tablet (`40000730:13363`): fluid, capped at 1023px (not 768px) — also confirms Tablet's own
//     real ceiling is 1023px, not this site's shared `breakpoints.xl` (1280px); see
//     RECENTLY_VIEWED_RAIL_DESKTOP_BREAKPOINT (app/constants) below for the direct consequence.
//   - Desktop (`40000307:12444`): fluid, genuinely UNBOUNDED — no max-width at all. Safe to leave
//     uncapped now (unlike before): the old cap existed specifically to stop `header` (width:100%)
//     drifting wider than `group` (self-limited to its own then-fixed-width children) on an
//     ultra-wide viewport — with cards now fluid too, `group` always tracks `container`'s own
//     width exactly like `header` does, so that divergence can no longer happen regardless of cap.
// audit-allow: derived composite, not itself a value with any promotable foundation-token
// equivalent — a "content max-width" isn't a spacing/sizing scale concept on its own.
const RAIL_CONTENT_MAX_WIDTH_MOBILE = '47.9375rem'; // 767px
const RAIL_CONTENT_MAX_WIDTH_TABLET = '63.9375rem'; // 1023px

// Deliberately NOT named DESKTOP_QUERY / sharing zimmProductCardShared.ts's constant of that
